require_once __DIR__.'/../includes/functions.php';student_only();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare("SELECT id,title FROM internships WHERE id=? AND ".active_internship_sql());$s->execute([$id?:0]);$i=$s->fetch();if(!$i){flash('warning','This internship is closed or unavailable.');redirect('/InternFinder/internships.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$check=$pdo->prepare("SELECT id FROM applications WHERE student_id=? AND internship_id=?");$check->execute([$_SESSION['student_id'],$i['id']]);if($check->fetch()){flash('warning','You have already applied for this internship.');redirect('my-applications.php');}
try{$ins=$pdo->prepare("INSERT INTO applications(student_id,internship_id) VALUES(?,?)");$ins->execute([$_SESSION['student_id'],$i['id']]);flash('success','Your application has been submitted.');}catch(PDOException $e){if($e->getCode()==='23000')flash('warning','You have already applied.');else{error_log($e->getMessage());flash('danger','Unable to submit application. Please try again.');}}redirect('my-applications.php');}
$pageTitle='Apply';include __DIR__.'/../includes/header.php'; ?>
